export interface BlurInOptions extends AnimOptions {
    /** Starting defocus radius in texels (Default: 24) */
    startRadius?: number;

    /** Target focal radius in texels (Default: 0 - completely sharp) */
    endRadius?: number;

    /** Whether to simultaneously fade in opacity from 0 to 1 (Default: false) */
    fadeIn?: boolean;

    /** Starting scale multiplier for subtle cinematic camera push-in (Default: 1.0) */
    startScale?: number;
}

import { Scene, RenderTarget, BlurIn, BlurOut, Text, Color, Rate } from "retiam";

const scene = new Scene({ canvas });

// 1. Offscreen RenderTarget containing presentation graphics
const target = new RenderTarget(scene, { width: 1280, height: 720 });
const title = new Text("QUANTUM COMPUTING", { fontSize: 64, fill: Color.WHITE });
target.scene.add(title);
scene.add(target.sprite);

// 2. Cinematic rack-focus entrance with camera breathing
await scene.play(new BlurIn(target, {
    startRadius: 36,
    endRadius: 0,
    fadeIn: true,
    startScale: 0.95,
    duration: 1400,
    rate_func: Rate.easeOutCubic()
}));

await scene.wait(1000);

// 3. Defocus exit
await scene.play(new BlurOut(target, {
    startRadius: 0,
    endRadius: 40,
    fadeOut: true,
    duration: 900
}));
